const { URL, format } = require('url')
const formatOptions = {
  auth: false,
  fragment: false,
  search: true,
  unicode: false,
}
const cacheKey = (request) => {
  const parsed = new URL(request.url)
  return `make-fetch-happen:request-cache:${format(parsed, formatOptions)}`
}
module.exports = cacheKey
